function syncAuth(){const u=user(),b=$('#loginOpen');if(b)b.textContent=token()&&u?'مرحباً، '+(u.username||'عضو'):'تسجيل الدخول';const p=$('.drawer-profile');if(p){p.querySelector('b').textContent=token()&&u?'أهلاً، '+u.username:'أهلاً بك في ملاذ';p.querySelector('small').textContent=token()&&u?({owner:'مالك المجتمع',admin:'إدارة ملاذ'}[u.role]||'عضو مسجل'):'اكتشف كل زاوية في مجتمعنا';p.querySelector('.profile-orb').textContent=token()&&u?(u.username||'م').slice(0,1).toUpperCase():'م'}all('[data-page="profile"],[data-page="admin"],[data-page="logout"],[data-page="addbot"]').forEach(n=>n.remove());const group=overlay?.querySelector('.drawer-bottom');if(token()&&u){const add=(id,title,sub,icon)=>{const b=el('button');b.dataset.page=id;b.innerHTML='<i>'+icon+'</i><span><b>'+title+'</b><small>'+sub+'</small></span><em>↙</em>';let section=overlay.querySelector('[data-account-links]');if(!section){section=el('div','drawer-links');section.dataset.accountLinks='true';const label=el('p','drawer-label','حسابك');group?.before(label);label.after(section)}section.append(b)};add('profile','ملفي الشخصي','إعدادات حسابك','◉');add('addbot','إضافة بوت','ربط بوتك بسيرفر Discord','＋');if(u.is_owner||['owner','admin'].includes(u.role))add('admin','لوحة الإدارة','إدارة مجتمع ملاذ','⌘');const b=el('button');b.dataset.page='logout';b.innerHTML='<i>↪</i><span><b>تسجيل الخروج</b><small>إنهاء جلسة الحساب</small></span><em>↙</em>';overlay.querySelector('[data-account-links]')?.append(b)}all('[data-page="zajel"],[data-page="groups"],[data-page="applications"],[data-page="tickets"],[data-page="bots"]').forEach(b=>{let m=b.querySelector('.lock-mark');if(token()){m?.remove()}else if(!m){m=el('em','lock-mark','🔒');b.append(m)}})}
